import React from 'react';

const Hero = () => {
  return (
    <section id="hero" style={{ textAlign: 'center', padding: '100px 20px' }}>
      <h1>Hi, I’m Krina Patel</h1>
      <h2>Mobile Application Developer</h2>
      <p>Passionate about turning ideas into seamless web and mobile experiences using React, React Native, and Firebase, delivering impact one project at a time.</p>

    </section>
  );
};

export default Hero;
